import {mkdir,writeFile} from 'node:fs/promises';import {chromium} from 'playwright';const out='artifacts/provider-current-20261016';await mkdir(out,{recursive:true});const browser=await chromium.launch({executablePath:process.env.HB_BROWSER_PATH,args:['--no-sandbox']});try{const page=await browser.newPage({viewport:{width:390,height:844}});await page.goto('https://hossambahr.com/ai/',{waitUntil:'networkidle'});await page.locator('#government-search').fill('رسوم تجديد بطاقة المنشأة لدى ICP في الشارقة');const pending=page.waitForResponse(r=>r.url().includes('/functions/v1/public-ai-concierge')&&r.request().method()==='POST',{timeout:90000});await page.locator('.hb-chat-send').click();const response=await pending,body=await response.text(),engines=[];for(const line of body.split('\n'))try{const x=JSON.parse(line.replace(/^data:\s*/,''));const e=(x.result||x).engine;if(e)engines.push(e);}catch{}const report={at:new Date().toISOString(),source:'REAL_PRODUCTION_NATIVE_REQUEST',requests:1,httpStatus:response.status(),engines,external_model_used:engines.some(e=>e.external_model_used===true),scope:'Provider status only; workflow success is not external-model acceptance.'};await writeFile(out+'/report.json',JSON.stringify(report,null,2));console.log(JSON.stringify(report));}finally{await browser.close();}